"""PDF de synthèse des TP et ADR d'une page, à partir des preuves existantes."""
from pathlib import Path
import json
from xml.sax.saxutils import escape
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,PageBreak,Image,Flowable
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib import colors
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from pypdf import PdfReader
R=Path(__file__).resolve().parents[1];O=R/'deliverables';O.mkdir(exist_ok=True)
font_pairs=[('/System/Library/Fonts/Supplemental/Arial.ttf','/System/Library/Fonts/Supplemental/Arial Bold.ttf'),('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf','/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf')]
a,b=next((a,b) for a,b in font_pairs if Path(a).exists());pdfmetrics.registerFont(TTFont('FL',a));pdfmetrics.registerFont(TTFont('FLB',b))
styles=getSampleStyleSheet()
for name,size,leading in [('FLBody',9.2,12.2),('FLTitle',23,27),('FLHead',12,15),('FLSmall',8,10.5)]:styles.add(ParagraphStyle(name,fontName='FLB' if name in ['FLTitle','FLHead'] else 'FL',fontSize=size,leading=leading,textColor=colors.HexColor('#26354b'),spaceAfter=7))
def p(s,style='FLBody'):return Paragraph(s.replace('₂','2'),styles[style])
def h(s):return p(s,'FLHead')
def table(headers,rows,widths):
 data=[[p(escape(str(v)),'FLSmall') for v in row] for row in [headers]+rows];t=Table(data,colWidths=widths)
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#eef0ff')),('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,0),1,colors.HexColor('#5865ee')),('LINEBELOW',(0,1),(-1,-1),.3,colors.HexColor('#e0e5ee')),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)]));return t

def footer(c,d):c.setFont('FL',8);c.setFillColor(colors.HexColor('#737b90'));c.drawString(40,25,'FraudLab - TP et projet commun - 23 novembre 2026');c.drawRightString(555,25,str(d.page))
def make(name,story):SimpleDocTemplate(str(O/name),pagesize=(595.28,841.89),leftMargin=40,rightMargin=40,topMargin=35,bottomMargin=43,title=name,author='Équipe FraudLab - réalisation assistée').build(story,onFirstPage=footer,onLaterPages=footer)
class C4(Flowable):
 def __init__(self):super().__init__();self.width=515;self.height=112
 def draw(self):
  c=self.canv;labels=['Analyste local','FastAPI / règles','A / B + DDPM','SQLite / preuves']
  for i,l in enumerate(labels):
   x=i*130;c.setFillColor(colors.HexColor('#eef0ff'));c.setStrokeColor(colors.HexColor('#cbd2ed'));c.roundRect(x,53,122,33,5,fill=1);c.setFillColor(colors.HexColor('#26354b'));c.setFont('FLB',8);c.drawCentredString(x+61,66,l)
   if i<3:c.setStrokeColor(colors.HexColor('#5865ee'));c.line(x+122,69,x+129,69)
  c.setFont('FL',8);c.drawString(0,33,'Frontière : Mac M2 / CPU / 127.0.0.1. Inférence sans flux externe.')
  c.drawString(0,17,'Préparation : téléchargements OpenML / Hugging Face aux versions figées.')
  c.drawString(0,1,'Aucun accès bancaire ; rôle analyste simulé ; validation humaine requise.')
s=[p('Architecture et décision ADR','FLTitle'),p('FraudLab - fraude bancaire, diffusion et Multi-LLM','FLSmall'),C4(),h('Décision et alternatives'),p('<b>Retenu :</b> service local FastAPI avec workers Transformers CPU. Le TP08 autorise l’adaptation de l’API existante. API managée : non retenue, transfert/coûts à autoriser. GPU cloud : non disponible et sans besoin démontré. Hybride : complexité non justifiée.'),table(['Dimension','Choix / preuve'],[['Données','OpenML1597 v1, PCA ; fixtures LLM fictives. Train/validation/test séparés. Données, poids, SQLite et secrets exclus du dépôt.'],['Modèles / versions','Détecteur pondéré seed42 ; DDPM100pas ; SmolLM2-360M et Qwen2.5-0.5B aux révisions de configs/llm_models.json.'],['Permissions / contrôles','Host/Origin et schémas ; admission1 ; deux appels max, 4600tokens, 20s/appel, 45s/demande, zéro retry. Aucun fallback cloud.'],['Qualification','smoke.json : vraie inférence. Charge1 : 12/12 contrats, p95 1,993s ; charge3 : 1/18, 17rejets429. Pas de SLO validé.'],['Panne / reprise','health200, ready503, reprise complète18,61s ; reprise ciblée10,38s. Sauvegarde/restauration SQLite vérifiée.'],['Économie / environnement','API0EUR ; coût complet et énergie réels ND. Scénario central : 8000EUR/an, ROI13,04% hypothétique. Calculs Green conditionnels séparés.'],['Exploitation','Opérateur de séance = personne qui lance le service ; interlocuteur et propriétaire nominatif à décider. Signalement sur écran local, pas d’envoi externe. Runbook, backup et rollback code documentés.']],[115,400]),h('GO sous conditions pour démonstration, NO-GO production bancaire'),p('Supervision humaine, usage benchmark/fictif, service uniquement local. Pas de SSO/TLS/haute disponibilité ; petits jeux et annotation humaine incomplète. Conserver le rapport déterministe si le LLM échoue. La diffusion et la cascade n’ont pas démontré leur supériorité.'),p('Objectifs futurs, non validés : p95&lt;5s et coût technique&lt;0,35EUR/demande, reprise&lt;60s. Preuves : docs/deployment_decision.md ; docs/incident_runbook.md ; evidence/ ; outputs/load_*. Décision du23/11/2026.','FLSmall')]
make('Architecture_ADR_FraudLab.pdf',s);assert len(PdfReader(O/'Architecture_ADR_FraudLab.pdf').pages)==1
n1=json.loads((R/'notebooks/TP01_FraudLab.ipynb').read_text());n2=json.loads((R/'notebooks/TP02_FraudLab.ipynb').read_text())
def outputs(nb):return '\n'.join(''.join(o.get('text',[])) for c in nb['cells'] if c['cell_type']=='code' for o in c['outputs'] if o['output_type']=='stream')
s=[p('TP01 - Génération et diffusion','FLTitle'),p('Scénario synthétique du cours ECE. Réalisation assistée par Codex, intégrée à FraudLab. Aucune observation bancaire.'),h('E1 / E2 - Générateurs et distributions'),p('Le générateur gaussien est reproductible ; le mélange conserve deux populations de poids70/30. Les quatre contrôles du sujet sont vérifiés avec assertions. Les sorties numériques exactes sont intégrées au notebook exécuté.'),Image(str(R/'experiments/tp01/figure_02.png'),width=500,height=190),h('E3 - Couverture'),p('La baseline à un seul mode ignore presque toute la population B, pourtant proche de30% dans la référence. Une bonne fidélité locale ne suffit pas pour augmenter des événements rares.'),Image(str(R/'experiments/tp01/figure_03.png'),width=500,height=170),p('Preuves : notebooks/TP01_FraudLab.ipynb ; experiments/tp01/execution.json ; quatre PNG. Exécution reproductible : python scripts/execute_course_notebooks.py.','FLSmall'),PageBreak(),p('TP01 - Forward et décision','FLTitle'),Image(str(R/'experiments/tp01/figure_04.png'),width=510,height=150),h('E4 - Forme directe et limites'),p('x_t = sqrt(alpha_bar) x_0 + sqrt(1-alpha_bar) epsilon. alpha_bar1 conserve x0 ; alpha_bar0 conserve seulement le bruit. SNR = alpha_bar/(1-alpha_bar). Une assertion vérifie aussi le cas0. Le forward n’apprend aucun réseau et n’est pas un générateur entraîné.'),h('E5 - Recommandation en cinq points'),p('1. Deux modes sont visibles ; une moyenne unique ne représente pas les deux groupes.<br/>2. La couverture de B distingue le mélange et la baseline, presque nulle pour cette dernière.<br/>3. Le bruitage est fixé ; il faut un reverse appris pour générer.<br/>4. Comparer fidélité, diversité et utilité avec splits indépendants, mêmes cas et plusieurs seeds.<br/>5. Refuser la baseline à un mode pour les événements rares ; valider sur données réelles autorisées avant tout usage métier.'),h('Transfert au projet bancaire'),p('Le DDPM bancaire reprend le bruitage et apprend le reverse en29 dimensions. Les exercices du TP restent séparés du benchmark réel ; l’augmentation est évaluée contre une référence pondérée, avec incertitude et absence de supériorité démontrée.'),p('Seed du TP01 :20261102. Référence scientifique : Ho, Jain et Abbeel (2020), DDPM. Les figures de référence, mélange, couverture et bruitage ont été réellement générées. Les réponses complètes sont dans le notebook.','FLSmall'),PageBreak(),p('TP02 - VAE, GAN et diversité','FLTitle'),h('E1 / E2 / E3 - Calculs vérifiés'),p('Reparamétrisation : z = mu + exp(0,5logvar) epsilon donne [1,5 ;0,5]. KL au prior =0 ; KL pour moyenne décalée =0,5nat. Pertes D et G calculées avec clipping des probabilités, y compris contrôle de finitude aux bornes0/1. Les trois vérifications du sujet réussissent.'),Image(str(R/'experiments/tp02/figure_01.png'),width=500,height=190),h('E4 - Diagnostic'),p('Mode collapse : couverture B proche de30% dans la référence, presque0% dans le générateur dégradé. Ne pas retenir ce générateur sur la seule plausibilité du mode majoritaire. Contrôler distribution, couverture et tâche aval sur une référence indépendante.'),h('Réflexion et lien FraudLab'),p('Le VAE transforme un bruit via un posterior dépendant de l’entrée pour différencier mu/sigma. Le GAN utilise un bruit de prior à l’entrée de G, sans exiger d’encodeur ni de KL. Les pertes adversariales seules ne garantissent ni diversité ni utilité. Le projet final retient le DDPM ; ces calculs ne prétendent pas entraîner un VAE/GAN bancaire.'),p('Seed1729 ; références : Kingma et Welling (2013), Goodfellow et al.(2014). Preuves : notebooks/TP02_FraudLab.ipynb et experiments/tp02/execution.json. Contributions humaines non attribuées.','FLSmall')]
make('TP01_TP02_Synthese_FraudLab.pdf',s);assert len(PdfReader(O/'TP01_TP02_Synthese_FraudLab.pdf').pages)==3
print('ADR :1page ; synthèse TP01/TP02 :3pages')
